return ['domain'=>'wp-theme-core','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'en_US','project-id-version'=>'','pot-creation-date'=>'2026-08-27T12:52:56+00:00','po-revision-date'=>'2026-10-01T12:14:49+00:00','x-generator'=>'Poedit 3.9','messages'=>['Applique la palette de couleurs du client à l\'administration et limite les jeux de couleurs proposés dans le profil.'=>'Applies the client\'s colour palette to the admin and limits the colour schemes offered in the profile.','Remplace le texte du pied de page de l\'administration par les crédits de l\'agence.'=>'Replaces the admin footer text with the agency credits.','Une création %s'=>'A creation %s','Une création %1$s — %2$s'=>'A creation %1$s — %2$s','Convertit au format WebP les images JPEG et PNG ajoutées à la médiathèque, miniatures comprises, pour alléger les pages.'=>'Converts JPEG and PNG images added to the media library to WebP, thumbnails included, to make pages lighter.','Masque la barre d\'administration sur le site public et retire le logo WordPress de l\'administration.'=>'Hides the admin bar on the public site and removes the WordPress logo from the admin.','Limite les blocs proposés dans l\'éditeur à une liste de blocs autorisés.'=>'Limits the blocks offered in the editor to a list of allowed blocks.','Désactive entièrement les commentaires : site public, administration, tableau de bord et API.'=>'Fully disables comments: public site, admin, dashboard and API.','Retire la page Réglages › Connectors (connexion à des fournisseurs d\'IA), inutilisée.'=>'Removes the Settings › Connectors page (connection to AI providers), which is unused.','Retire du tableau de bord le panneau de bienvenue et les modules par défaut (Activité, Brouillon rapide, actualités WordPress).'=>'Removes the welcome panel and the default widgets (Activity, Quick Draft, WordPress news) from the dashboard.','Remplace l\'éditeur de blocs par l\'éditeur classique, pour tous les contenus et pour les widgets.'=>'Replaces the block editor with the classic editor, for all content and for widgets.','Bloque l\'accès au Personnaliseur, à l\'Éditeur de site et aux Polices pour le thème actif, sans empêcher l\'aperçu des autres thèmes.'=>'Blocks access to the Customizer, Site Editor and Fonts for the active theme, while still allowing other themes to be previewed.','Retire le sélecteur de langue de la page de connexion.'=>'Removes the language switcher from the login page.','Retire le lien « Politique de confidentialité » du pied de la page de connexion.'=>'Removes the “Privacy Policy” link from the login page footer.','Retire les réglages de couleur et de typographie des blocs de l\'éditeur : la mise en forme reste celle du thème.'=>'Removes the colour and typography settings from editor blocks: styling stays in the hands of the theme.','Désactive la publication d\'articles par e-mail et masque ses réglages dans Réglages › Écriture.'=>'Disables posting by email and hides its settings in Settings › Writing.','Masque le réglage « Icône du site » de Réglages › Général.'=>'Hides the “Site Icon” setting in Settings › General.','Désactive les mises à jour automatiques des extensions, des thèmes, des traductions et des versions majeures de WordPress. Les mises à jour de sécurité restent automatiques.'=>'Disables automatic updates for plugins, themes, translations and major WordPress versions. Security updates remain automatic.','Désactive toutes les mises à jour automatiques : WordPress, extensions, thèmes et traductions.'=>'Disables all automatic updates: WordPress, plugins, themes and translations.','Désactive les services de mise à jour : plus aucun ping n\'est envoyé aux annuaires de blogs à la publication d\'un article.'=>'Disables update services: no more pings are sent to blog directories when a post is published.','Affiche le contenu dans l\'éditeur de blocs avec les styles du thème.'=>'Displays content in the block editor with the theme\'s styles.','Applique le logo et les couleurs du thème à la page de connexion.'=>'Applies the theme\'s logo and colours to the login page.','Ajoute à l\'éditeur de blocs un interrupteur « Afficher le titre », commun à toutes les pages.'=>'Adds a “Show title” toggle to the block editor, shared by all pages.','Titre'=>'Title','Afficher le titre'=>'Show the title','Réglage global : le titre est affiché dans l’éditeur, sur tous les contenus concernés.'=>'Site-wide setting: the title is shown in the editor, on every content type concerned.','Réglage global : le titre est masqué dans l’éditeur, sur tous les contenus concernés ; il reste modifiable en haut de cette barre latérale.'=>'Site-wide setting: the title is hidden in the editor, on every content type concerned; it remains editable at the top of this sidebar.','Le réglage n’a pas pu être enregistré.'=>'The setting could not be saved.','Autorise l\'ajout d\'images SVG dans la médiathèque, après les avoir nettoyées de tout code exécutable.'=>'Allows SVG images to be added to the media library, once cleaned of any executable code.','Vous n’êtes pas autorisé à envoyer des fichiers SVG.'=>'You are not allowed to upload SVG files.','Le fichier SVG n’a pas pu être lu.'=>'The SVG file could not be read.','Ce fichier SVG a été refusé : il est invalide ou contient du code non autorisé.'=>'This SVG file was rejected: it is invalid or contains unauthorized code.','Le fichier SVG n’a pas pu être nettoyé avant son enregistrement.'=>'The SVG file could not be cleaned up before it was saved.','Charge les feuilles de styles et les scripts du thème sur le site public.'=>'Loads the theme\'s stylesheets and scripts on the public site.','Retire du code des pages les balises inutiles ou qui révèlent la version de WordPress.'=>'Removes from page markup the tags that are useless or that reveal the WordPress version.','Retire du site public les feuilles de styles de l\'éditeur de blocs, inutiles au thème.'=>'Removes the block editor stylesheets, which the theme does not need, from the public site.','Ne charge plus la police d\'icônes Dashicons pour les visiteurs non connectés.'=>'No longer loads the Dashicons icon font for logged-out visitors.','Désactive les scripts et styles d\'emojis ajoutés par WordPress.'=>'Disables the emoji scripts and styles added by WordPress.','Désactive les requêtes périodiques Heartbeat sur le site public.'=>'Disables periodic Heartbeat requests on the public site.','Fournit au thème les favicons (versions claire et sombre) et la couleur de l\'onglet du navigateur.'=>'Provides the theme with its favicons (light and dark versions) and the browser tab colour.','Désactive les mots de passe d\'application, qui permettent à un logiciel externe de se connecter au site.'=>'Disables application passwords, which let external software connect to the site.','Empêche les visiteurs de découvrir les identifiants des comptes (API, archives d\'auteur, flux RSS, sitemap).'=>'Prevents visitors from discovering account usernames (API, author archives, RSS feeds, sitemap).','Ferme l\'API XML-RPC (xmlrpc.php), ancienne porte d\'entrée souvent visée par les attaques.'=>'Closes the XML-RPC API (xmlrpc.php), a legacy entry point frequently targeted by attacks.','Affiche le même message à la connexion et au mot de passe oublié, pour ne pas révéler quels comptes existent.'=>'Shows the same message on login and lost password, so as not to reveal which accounts exist.','Identifiant ou mot de passe incorrect.'=>'Incorrect login or password.','Ajoute aux pages publiques des en-têtes HTTP de sécurité, qui empêchent notamment d\'afficher le site dans une iframe d\'un autre domaine.'=>'Adds HTTP security headers to public pages, notably preventing the site from being displayed in an iframe on another domain.','Compose le titre des pages, affiché dans l\'onglet du navigateur et dans les résultats des moteurs de recherche.'=>'Builds the page title shown in the browser tab and in search engine results.','Ajoute aux pages la meta description lue par les moteurs de recherche, ou à défaut l\'extrait du contenu.'=>'Adds to pages the meta description read by search engines, or the content excerpt if there is none.','Ajoute les balises Open Graph : titre, description et image affichés quand un lien vers le site est partagé.'=>'Adds Open Graph tags: the title, description and image shown when a link to the site is shared.','Ajoute à l\'éditeur de blocs un panneau SEO : meta description et exclusion du sitemap.'=>'Adds an SEO panel to the block editor: meta description and sitemap exclusion.','SEO'=>'SEO','Meta description'=>'Meta description','%1$d/%2$d caractères'=>'%1$d/%2$d characters','%1$d caractères — au-delà des %2$d recommandés par Google'=>'%1$d characters — beyond the %2$d recommended by Google','Sitemap'=>'Sitemap','Inclure cette page dans le sitemap'=>'Include this page in the sitemap','Désactiver retire ce contenu des sitemaps XML générés par WordPress.'=>'Disabling removes this content from the XML sitemaps generated by WordPress.','Retire du sitemap XML les contenus marqués comme exclus.'=>'Removes content marked as excluded from the XML sitemap.','Déclare les emplacements de menus du thème (Apparence › Menus).'=>'Registers the theme\'s menu locations (Appearance › Menus).','Active les fonctionnalités WordPress utilisées par le thème (titre des pages, images à la une, HTML5…).'=>'Enables the WordPress features used by the theme (page titles, featured images, HTML5…).','Outil de développement : affiche lisiblement les variables dans les templates, sans effet en production.'=>'Development tool: displays template variables in a readable way, no effect in production.','Fonctionnalités du thème'=>'Theme features','Fonctionnalités activées par le thème, regroupées par provider, dans leur ordre de chargement.'=>'Features enabled by the theme, grouped by provider, in loading order.','Fonctionnalité'=>'Feature','Description'=>'Description','Aucune fonctionnalité dans cette catégorie.'=>'No features in this category.','Projet <span class="count">(%s)</span>'=>'Project <span class="count">(%s)</span>' . "\0" . 'Project <span class="count">(%s)</span>','Générique <span class="count">(%s)</span>'=>'Generic <span class="count">(%s)</span>' . "\0" . 'Generic <span class="count">(%s)</span>']];